.ds {
  color:var(--p-ink); background:var(--p-bg); font:var(--p-type-body);
  color-scheme:light; word-break:keep-all; overflow-wrap:anywhere; text-align:left;
}
.ds,.ds * { box-sizing:border-box; }
.ds [hidden] { display:none!important; }
.ds :is(h1,h2,h3,p,fieldset) { margin:0; }
.ds :is(button,input,select,textarea) { font:inherit; color:inherit; letter-spacing:inherit; }
.ds :is(code,pre) { font-family:var(--p-mono-font); }
.ds button { cursor:pointer; touch-action:manipulation; }
.ds button:disabled { cursor:not-allowed; }
.ds :is(button,input,select,textarea,a,[tabindex]):focus-visible { outline:var(--p-border-width-focus) solid var(--p-highlight); outline-offset:var(--p-focus-offset); }
.ds .ui-icon { display:inline-block; width:var(--p-icon-lg); height:var(--p-icon-lg); object-fit:contain; flex-shrink:0; vertical-align:middle; }
.ds .ds-demo-note { font-size:var(--p-text-sm); margin-top:var(--p-space-sm); min-height:calc(var(--p-space-unit) * 5); color:var(--p-muted); }
.ds .ds-surface { border:var(--p-border-width) solid var(--p-line); border-radius:var(--p-radius); background:var(--p-surface); }
.ds .ds-surface[data-material="raised"] { box-shadow:var(--p-shadow); border-color:var(--p-edge); }
.ds .ds-surface[data-material="inset"] { box-shadow:var(--p-inset); background:var(--p-bg); }
.ds .ds-surface[data-material="glass"] { background:var(--p-high); box-shadow:var(--p-glass-shadow); }
@supports (backdrop-filter:blur(0)) { .ds .ds-surface[data-material="glass"] { background:var(--p-glass); backdrop-filter:var(--p-blur-md); } }
@media(prefers-reduced-transparency:reduce) { .ds .ds-surface[data-material="glass"] { background:var(--p-high); backdrop-filter:none; } }
@media(prefers-reduced-motion:reduce) { .ds * { transition:none!important; animation:none!important; } }
.ds .ds-token-row { display:flex; flex-wrap:wrap; align-items:center; gap:var(--p-space-sm); }
.ds .ds-admin-error { color:var(--p-error); font-size:var(--p-text-body); }

.ds .ds-layout { min-inline-size:0; max-inline-size:100%; gap:var(--p-space-lg); }
.ds .ds-layout > * { min-inline-size:0; }
.ds .ds-layout:not(.ds-toolbar-spacer) { container-type:inline-size; container-name:pattove-layout; }
.ds .ds-layout :is(img,video,svg) { max-inline-size:100%; }
.ds .ds-layout-copy,.ds .ds-layout-tile { display:grid; gap:var(--p-space-md); align-content:start; }
.ds .ds-layout-tile { padding:var(--p-space-lg); border:var(--p-border-width) solid var(--p-line); border-radius:var(--p-radius); background:var(--p-surface); }
.ds .ds-layout :is(h2,h3) { font-size:var(--p-text-title); }
.ds .ds-layout :is(ul,ol) { padding-inline-start:var(--p-space-lg); }
.ds .ds-layout-aside,.ds .ds-layout-secondary { padding:var(--p-space-md); background:var(--p-soft); border-radius:var(--p-radius); }
.ds .ds-layout-media { min-block-size:calc(var(--p-space-unit) * 48); padding:var(--p-space-xl); display:flex; flex-direction:column; justify-content:end; gap:var(--p-space-sm); background:var(--p-accent); color:var(--p-on-accent); border-radius:var(--p-radius); }
.ds .ds-layout-media strong { font-size:var(--p-text-heading); }
.ds .ds-layout a { color:var(--p-ink); text-underline-offset:var(--p-space-2xs); }
.ds .ds-layout :is(header,footer) { display:flex; flex-wrap:wrap; align-items:center; justify-content:space-between; gap:var(--p-space-md); }
.ds .ds-layout nav { display:flex; flex-wrap:wrap; gap:var(--p-space-md); }

.ds .ds-reading-layout { max-inline-size:var(--p-measure); margin-inline:auto; padding:var(--p-space-lg); }
.ds :is(.ds-sidebar-layout,.ds-split-layout,.ds-sticky-sidebar,.ds-supporting-pane,.ds-settings-layout) { display:flex; flex-wrap:wrap; align-items:start; }
.ds :is(.ds-sidebar-layout,.ds-sticky-sidebar,.ds-supporting-pane,.ds-settings-layout) > .ds-layout-body { flex:999 1 var(--p-container-sm); }
.ds :is(.ds-sidebar-layout,.ds-sticky-sidebar,.ds-supporting-pane,.ds-settings-layout) > .ds-layout-aside { flex:1 1 var(--p-container-2xs); }
.ds .ds-split-layout > * { flex:1 1 var(--p-container-2xs); }
.ds .ds-sticky-sidebar > .ds-layout-aside { position:sticky; inset-block-start:var(--p-space-md); max-block-size:calc(100dvh - var(--p-space-xl)); overflow:auto; }
.ds :is(.ds-grid-layout,.ds-bento-layout,.ds-fluid-layout,.ds-wide-grid-block,.ds-equal-height-grid) { display:grid; grid-template-columns:repeat(auto-fit,minmax(min(100%,var(--p-container-2xs)),1fr)); }
.ds .ds-masonry-layout { columns:var(--p-container-2xs); column-gap:var(--p-space-lg); }
.ds .ds-masonry-layout > * { break-inside:avoid; margin-block-end:var(--p-space-lg); }
.ds .ds-bento-layout,.ds .ds-wide-grid-block { container-type:inline-size; }
.ds .ds-bento-layout > :first-child { background:var(--p-soft); }
@container pattove-layout (min-width:580px) { .ds :is(.ds-bento-layout,.ds-wide-grid-block) > :first-child { grid-column:span 2; } }
.ds .ds-full-bleed-layout { inline-size:100%; }
.ds .ds-full-bleed-layout > * { inline-size:100%; border-radius:0; }
.ds .ds-alternating-layout { display:grid; }
.ds .ds-layout-pair { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:var(--p-space-lg); align-items:center; }
.ds .ds-layout-pair:nth-child(even) > :first-child { order:2; }
.ds .ds-print-layout { max-inline-size:var(--p-measure); margin-inline:auto; display:grid; gap:var(--p-space-xl); }
.ds .ds-stack-layout { display:flex; flex-direction:column; }
.ds .ds-cluster-layout { display:flex; flex-wrap:wrap; align-items:center; }
.ds .ds-switcher-layout { display:flex; flex-wrap:wrap; }
.ds .ds-switcher-layout > * { flex:1 1 calc((var(--p-container-xl) - 100%) * 999); }
.ds .ds-reel-layout { display:flex; overflow-x:auto; scroll-snap-type:x proximity; padding-block:var(--p-space-xs); }
.ds .ds-reel-layout > * { flex:0 0 min(calc(100% * 5 / 6),var(--p-container-xs)); scroll-snap-align:start; }
.ds .ds-cover-layout { display:flex; flex-direction:column; min-block-size:calc(100dvh * 3 / 5); padding:var(--p-space-lg); }
.ds .ds-cover-layout .ds-layout-center { margin-block:auto; padding-block:var(--p-space-xl); }
.ds .ds-frame-layout { aspect-ratio:var(--p-aspect-landscape); overflow:hidden; }
.ds .ds-frame-layout > * { inline-size:100%; block-size:100%; min-block-size:0; object-fit:cover; }
.ds .ds-imposter-layout { display:grid; isolation:isolate; }
.ds .ds-imposter-layout > * { grid-area:1/1; }
.ds .ds-imposter-layout > .ds-layout-overlay { place-self:center; max-inline-size:calc(100% - var(--p-space-lg)); max-block-size:calc(100% - var(--p-space-lg)); overflow:auto; padding:var(--p-space-md); background:var(--p-surface); border:var(--p-border-width) solid var(--p-line); border-radius:var(--p-radius); }
.ds :is(.ds-holy-grail-layout,.ds-three-pane-layout,.ds-editor-layout) { display:grid; grid-template-columns:minmax(0,1fr) minmax(0,2fr) minmax(0,1fr); align-items:start; }
.ds .ds-editor-layout > * { min-block-size:calc(var(--p-space-unit) * 64); }
.ds .ds-letterbox-layout { display:grid; place-items:center; background:var(--p-ink); padding:var(--p-space-md); min-block-size:calc(100dvh * 2 / 5); }
.ds .ds-letterbox-layout > * { aspect-ratio:var(--p-aspect-landscape); inline-size:100%; max-inline-size:var(--p-container-xl); min-block-size:0; object-fit:contain; }
.ds .ds-breakout-layout { display:grid; grid-template-columns:minmax(0,1fr) minmax(0,var(--p-measure)) minmax(0,1fr); row-gap:var(--p-space-xl); }
.ds .ds-breakout-layout > .ds-layout-body { grid-column:2; }
.ds .ds-breakout-layout > .ds-layout-breakout { grid-column:1/-1; }
.ds .ds-toolbar-spacer { flex:1 1 auto; min-inline-size:var(--p-space-md); }
.ds :is(.ds-scroll-area,.ds-scroll-fog) { max-block-size:calc(var(--p-space-unit) * 64); overflow:auto; overscroll-behavior:contain; scrollbar-width:thin; scrollbar-color:var(--p-muted) var(--p-surface); padding:var(--p-space-md); border:var(--p-border-width) solid var(--p-line); border-radius:var(--p-radius); }
.ds :is(.ds-scroll-area,.ds-scroll-fog) > * + * { margin-block-start:var(--p-space-md); }
.ds .ds-scroll-fog { background:linear-gradient(var(--p-bg) 50%,transparent) center top / 100% var(--p-space-xl) no-repeat local,linear-gradient(transparent,var(--p-bg) 50%) center bottom / 100% var(--p-space-xl) no-repeat local,radial-gradient(farthest-side at 50% 0,var(--p-line),transparent) center top / 100% var(--p-space-md) no-repeat scroll,radial-gradient(farthest-side at 50% 100%,var(--p-line),transparent) center bottom / 100% var(--p-space-md) no-repeat scroll; }
.ds .ds-generic-header { display:flex; flex-wrap:wrap; align-items:center; justify-content:space-between; padding:var(--p-space-lg); border-block-end:var(--p-border-width) solid var(--p-line); }
.ds .ds-bottom-info-bar { position:sticky; inset-block-end:0; padding:var(--p-space-md); background:var(--p-surface); border-block-start:var(--p-border-width) solid var(--p-line); }
.ds .ds-column-drop-layout { display:flex; flex-wrap:wrap; align-items:start; }
.ds .ds-column-drop-layout > * { flex:1 1 var(--p-container-2xs); }
.ds .ds-column-drop-layout > .ds-layout-body { flex-grow:2; flex-basis:var(--p-container-sm); }
.ds .ds-layout-shifter { display:grid; grid-template-columns:minmax(0,1fr) minmax(0,3fr); }
.ds .ds-layout-shifter > .ds-layout-aside { grid-row:span 2; }
.ds .ds-layout-shifter > .ds-layout-secondary { grid-column:2; }
.ds .ds-tiny-tweaks-layout { max-inline-size:var(--p-measure); margin-inline:auto; padding:var(--p-space-lg); font-size:var(--p-text-body); }
.ds .ds-equal-columns { display:grid; grid-template-columns:repeat(auto-fit,minmax(min(100%,var(--p-container-2xs)),1fr)); max-inline-size:calc(var(--p-container-2xs) * 3 + var(--p-space-lg) * 2); }
.ds .ds-equal-columns[data-columns="2"] { max-inline-size:calc(var(--p-container-2xs) * 2 + var(--p-space-lg) * 1); }
.ds .ds-equal-columns[data-columns="4"] { max-inline-size:calc(var(--p-container-2xs) * 4 + var(--p-space-lg) * 3); }
.ds .ds-equal-columns[data-columns="5"] { max-inline-size:calc(var(--p-container-2xs) * 5 + var(--p-space-lg) * 4); }
.ds .ds-equal-columns[data-columns="6"] { max-inline-size:calc(var(--p-container-2xs) * 6 + var(--p-space-lg) * 5); }
.ds .ds-equal-height-grid { grid-auto-rows:1fr; }
.ds .ds-thumbnail-list { container-type:inline-size; list-style:none; padding:0; margin:0; display:grid; }
.ds .ds-thumbnail-list > li { display:flex; align-items:center; gap:var(--p-space-md); padding-block:var(--p-space-md); border-block-end:var(--p-border-width) solid var(--p-line); }
.ds .ds-layout-thumb { flex:0 0 var(--p-control-size-xl); aspect-ratio:var(--p-aspect-square); display:grid; place-items:center; background:var(--p-soft); border-radius:var(--p-radius); }
.ds .ds-thumbnail-list > li p { margin-block-start:var(--p-space-xs); }
@container(max-width:440px) { .ds .ds-thumbnail-list > li p { display:none; } }
@media(max-width:760px) {
 .ds :is(.ds-holy-grail-layout,.ds-three-pane-layout,.ds-editor-layout,.ds-layout-shifter,.ds-equal-columns) { grid-template-columns:minmax(0,1fr); }
 .ds .ds-layout-shifter > * { grid-column:auto; grid-row:auto; }
 .ds .ds-layout-pair { grid-template-columns:minmax(0,1fr); }
 .ds .ds-layout-pair:nth-child(even) > :first-child { order:0; }
 .ds .ds-sticky-sidebar > .ds-layout-aside { position:static; max-block-size:none; }
}
@media print {
 .ds .ds-print-layout { display:block; max-inline-size:none; padding:0; }
 .ds .ds-print-layout .ds-layout-no-print { display:none; }
 .ds .ds-print-layout .ds-layout-page-break { break-before:page; }
 .ds .ds-print-layout :is(h1,h2,h3) { break-after:avoid; }
 .ds .ds-print-layout :is(img,table,figure) { break-inside:avoid; }
 .ds :is(.ds-bottom-info-bar,.ds-sticky-sidebar > .ds-layout-aside) { position:static; }
}

